INSERT INTO `sys_i18n` VALUES (10393, 'clickhouse_asynchronous_metrics_jemalloc_resident_desc', 'zh', 'clickhouse_asynchronous_metrics_jemalloc_resident_desc', '低级内存分配器（jemalloc）的内部度量', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10394, 'clickhouse_asynchronous_metrics_jemalloc_retained_desc', 'zh', 'clickhouse_asynchronous_metrics_jemalloc_retained_desc', '低级内存分配器（jemalloc）的内部度量', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10395, 'clickhouse_asynchronous_metrics_jitter_desc', 'zh', 'clickhouse_asynchronous_metrics_jitter_desc', '用于计算异步度量的线程计划唤醒的时间与实际唤醒的时间之间的差异。总体系统延迟和响应性的代理指示器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10396, 'clickhouse_asynchronous_metrics_load_average1_desc', 'zh', 'clickhouse_asynchronous_metrics_load_average1_desc', '整个系统负载，在1分钟内用指数平滑进行平均。负载表示所有进程（OS内核的调度实体）上的线程数，这些线程当前正在由CPU运行或等待IO，或准备运行但此时未被调度。这个数字包括所有进程', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10397, 'clickhouse_asynchronous_metrics_load_average15_desc', 'zh', 'clickhouse_asynchronous_metrics_load_average15_desc', '整个系统负载，在15分钟内用指数平滑进行平均。负载表示所有进程（OS内核的调度实体）上的线程数，这些线程当前正在由CPU运行或等待IO，或准备运行但此时未被调度。这个数字包括所有进程', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10398, 'clickhouse_asynchronous_metrics_load_average5_desc', 'zh', 'clickhouse_asynchronous_metrics_load_average5_desc', '整个系统负载，在5分钟内用指数平滑进行平均。负载表示所有进程（OS内核的调度实体）上的线程数，这些线程当前正在由CPU运行或等待IO，或准备运行但此时未被调度。这个数字包括所有进程', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10399, 'clickhouse_asynchronous_metrics_m_map_cache_cells_desc', 'zh', 'clickhouse_asynchronous_metrics_m_map_cache_cells_desc', '使用“mmap”打开的文件数（映射到内存中）。这用于将“local_filesystem_read_method”设置为“mmap”的查询。使用“mmap”打开的文件保存在缓存中，以避免昂贵的TLB刷新', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10400, 'clickhouse_asynchronous_metrics_mark_cache_bytes_desc', 'zh', 'clickhouse_asynchronous_metrics_mark_cache_bytes_desc', '标记缓存的总大小（字节）', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10401, 'clickhouse_asynchronous_metrics_mark_cache_files_desc', 'zh', 'clickhouse_asynchronous_metrics_mark_cache_files_desc', '标记缓存中缓存的标记文件总数', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10402, 'clickhouse_asynchronous_metrics_max_part_count_for_partition_desc', 'zh', 'clickhouse_asynchronous_metrics_max_part_count_for_partition_desc', 'MergeTree族所有表的所有分区中每个分区的最大部件数。大于300的值表示配置错误、过载或大量数据加载', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10403, 'clickhouse_asynchronous_metrics_memory_code_desc', 'zh', 'clickhouse_asynchronous_metrics_memory_code_desc', '为服务器进程的机器代码页映射的虚拟内存量，以字节为单位', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10404, 'clickhouse_asynchronous_metrics_memory_data_and_stack_desc', 'zh', 'clickhouse_asynchronous_metrics_memory_data_and_stack_desc', '为使用堆栈和分配的内存而映射的虚拟内存量，以字节为单位。它是否包括每线程堆栈和大多数分配的内存，这是通过“mmap”系统调用分配的，这一点尚未明确。此度量仅出于完整性原因而存在。建议使用“MemoryResident”度量进行监控', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10405, 'clickhouse_asynchronous_metrics_memory_resident_desc', 'zh', 'clickhouse_asynchronous_metrics_memory_resident_desc', '服务器进程使用的物理内存量，以字节为单位', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10406, 'clickhouse_asynchronous_metrics_memory_shared_desc', 'zh', 'clickhouse_asynchronous_metrics_memory_shared_desc', '服务器进程使用的内存量，也由其他进程共享，以字节为单位。ClickHouse不使用共享内存，但由于自身原因，某些内存可能会被OS标记为共享。这个指标没有太多意义，它的存在只是出于完整性的原因', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10407, 'clickhouse_asynchronous_metrics_memory_virtual_desc', 'zh', 'clickhouse_asynchronous_metrics_memory_virtual_desc', '服务器进程分配的虚拟地址空间的大小，以字节为单位。虚拟地址空间的大小通常比物理内存消耗大得多，不应用作内存消耗的估计值。该度量的大值完全正常，仅在技术上有意义', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10408, 'clickhouse_asynchronous_metrics_my_sql_threads_desc', 'zh', 'clickhouse_asynchronous_metrics_my_sql_threads_desc', 'MySQL兼容协议服务器中的线程数', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10409, 'clickhouse_asynchronous_metrics_network_receive_bytes_ens33_desc', 'zh', 'clickhouse_asynchronous_metrics_network_receive_bytes_ens33_desc', '通过网络接口接收的字节数。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10410, 'clickhouse_asynchronous_metrics_network_receive_bytes_virbr0_desc', 'zh', 'clickhouse_asynchronous_metrics_network_receive_bytes_virbr0_desc', '通过网络接口接收的字节数。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10411, 'clickhouse_asynchronous_metrics_network_receive_bytes_virbr0_nic_desc', 'zh', 'clickhouse_asynchronous_metrics_network_receive_bytes_virbr0_nic_desc', '通过网络接口接收的字节数。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
