INSERT INTO `sys_i18n` VALUES (10433, 'clickhouse_asynchronous_metrics_number_of_databases_desc', 'zh', 'clickhouse_asynchronous_metrics_number_of_databases_desc', '服务器上的数据库总数', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10434, 'clickhouse_asynchronous_metrics_number_of_detached_by_user_parts_desc', 'zh', 'clickhouse_asynchronous_metrics_number_of_detached_by_user_parts_desc', '用户使用“ALTER TABLE DETACH”查询从MergeTree表中分离的部件总数（与意外、损坏或忽略的部件相反）。服务器不关心分离的部件，它们可以被移除', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10435, 'clickhouse_asynchronous_metrics_number_of_detached_parts_desc', 'zh', 'clickhouse_asynchronous_metrics_number_of_detached_parts_desc', '从MergeTree表分离的部件总数。用户可以使用“ALTER TABLE DETACH”查询分离部件，或者在部件损坏、意外或不需要时由服务器本身分离部件。服务器不关心分离的部件，它们可以被移除', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10436, 'clickhouse_asynchronous_metrics_number_of_tables_desc', 'zh', 'clickhouse_asynchronous_metrics_number_of_tables_desc', '服务器上所有数据库的合计表总数，不包括不能包含MergeTree表的数据库。排除的数据库引擎是那些动态生成表集的引擎，如“Lazy”、“MySQL”、“PostgreSQL”、“SQlite”', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10437, 'clickhouse_asynchronous_metrics_os_context_switches_desc', 'zh', 'clickhouse_asynchronous_metrics_os_context_switches_desc', '系统在主机上经历的上下文切换数。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10438, 'clickhouse_asynchronous_metrics_os_guest_nice_time_desc', 'zh', 'clickhouse_asynchronous_metrics_os_guest_nice_time_desc', '当来宾被设置为更高优先级时，在Linux内核的控制下为来宾操作系统运行虚拟CPU所花费的时间比率（参见“man-procfs”）。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。该指标与ClickHouse无关，但仍存在完整性。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10439, 'clickhouse_asynchronous_metrics_os_guest_nice_time_cpu0_desc', 'zh', 'clickhouse_asynchronous_metrics_os_guest_nice_time_cpu0_desc', '当来宾被设置为更高优先级时，在Linux内核的控制下为来宾操作系统运行虚拟CPU所花费的时间比率（参见“man-procfs”）。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。该指标与ClickHouse无关，但仍存在完整性。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
