INSERT INTO `sys_i18n` VALUES (10447, 'clickhouse_asynchronous_metrics_os_guest_nice_time_normalized_desc', 'zh', 'clickhouse_asynchronous_metrics_os_guest_nice_time_normalized_desc', '该值类似于“OSGuestIceTime”，但除以[0..1]间隔内要测量的CPU核数，而不考虑核数。这允许您在集群中的多个服务器上平均该指标的值，即使核心数量不一致，也仍然可以获得平均资源利用率指标', '', '2023-03-20 14:40:00', 415);
