INSERT INTO `sys_i18n` VALUES (10455, 'clickhouse_asynchronous_metrics_os_guest_time_cpu6_desc', 'zh', 'clickhouse_asynchronous_metrics_os_guest_time_cpu6_desc', '在Linux内核的控制下为来宾操作系统运行虚拟CPU所花费的时间比率（请参见“man-procfs”）。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。该指标与ClickHouse无关，但仍存在完整性。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10456, 'clickhouse_asynchronous_metrics_os_guest_time_cpu7_desc', 'zh', 'clickhouse_asynchronous_metrics_os_guest_time_cpu7_desc', '在Linux内核的控制下为来宾操作系统运行虚拟CPU所花费的时间比率（请参见“man-procfs”）。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。该指标与ClickHouse无关，但仍存在完整性。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10457, 'clickhouse_asynchronous_metrics_os_guest_time_normalized_desc', 'zh', 'clickhouse_asynchronous_metrics_os_guest_time_normalized_desc', '该值类似于“OSGuestTime”，但除以[0..1]间隔内要测量的CPU核数，而不考虑核数。这允许您在集群中的多个服务器上平均该指标的值，即使核心数量不一致，也仍然可以获得平均资源利用率指标', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10458, 'clickhouse_asynchronous_metrics_os_idle_time_desc', 'zh', 'clickhouse_asynchronous_metrics_os_idle_time_desc', '从OS内核的角度来看，CPU内核空闲（甚至没有准备好运行等待IO的进程）的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。这不包括由于CPU内部原因（内存负载、管道暂停、分支预测失误、运行另一个SMT内核）导致CPU利用率不足的时间。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10459, 'clickhouse_asynchronous_metrics_os_idle_time_cpu0_desc', 'zh', 'clickhouse_asynchronous_metrics_os_idle_time_cpu0_desc', '从OS内核的角度来看，CPU内核空闲（甚至没有准备好运行等待IO的进程）的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。这不包括由于CPU内部原因（内存负载、管道暂停、分支预测失误、运行另一个SMT内核）导致CPU利用率不足的时间。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10460, 'clickhouse_asynchronous_metrics_os_idle_time_cpu1_desc', 'zh', 'clickhouse_asynchronous_metrics_os_idle_time_cpu1_desc', '从OS内核的角度来看，CPU内核空闲（甚至没有准备好运行等待IO的进程）的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。这不包括由于CPU内部原因（内存负载、管道暂停、分支预测失误、运行另一个SMT内核）导致CPU利用率不足的时间。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10461, 'clickhouse_asynchronous_metrics_os_idle_time_cpu2_desc', 'zh', 'clickhouse_asynchronous_metrics_os_idle_time_cpu2_desc', '从OS内核的角度来看，CPU内核空闲（甚至没有准备好运行等待IO的进程）的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。这不包括由于CPU内部原因（内存负载、管道暂停、分支预测失误、运行另一个SMT内核）导致CPU利用率不足的时间。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
