INSERT INTO `sys_i18n` VALUES (10474, 'clickhouse_asynchronous_metrics_os_irq_time_cpu4_desc', 'zh', 'clickhouse_asynchronous_metrics_os_irq_time_cpu4_desc', '在CPU上运行硬件中断请求所花费的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。此度量值的高值可能表示硬件配置错误或网络负载非常高。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10475, 'clickhouse_asynchronous_metrics_os_irq_time_cpu5_desc', 'zh', 'clickhouse_asynchronous_metrics_os_irq_time_cpu5_desc', '在CPU上运行硬件中断请求所花费的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。此度量值的高值可能表示硬件配置错误或网络负载非常高。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10476, 'clickhouse_asynchronous_metrics_os_irq_time_cpu6_desc', 'zh', 'clickhouse_asynchronous_metrics_os_irq_time_cpu6_desc', '在CPU上运行硬件中断请求所花费的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。此度量值的高值可能表示硬件配置错误或网络负载非常高。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10477, 'clickhouse_asynchronous_metrics_os_irq_time_cpu7_desc', 'zh', 'clickhouse_asynchronous_metrics_os_irq_time_cpu7_desc', '在CPU上运行硬件中断请求所花费的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。此度量值的高值可能表示硬件配置错误或网络负载非常高。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10478, 'clickhouse_asynchronous_metrics_os_irq_time_normalized_desc', 'zh', 'clickhouse_asynchronous_metrics_os_irq_time_normalized_desc', '该值类似于“OSIrqTime”，但除以[0..1]间隔内要测量的CPU核数，而不考虑核数。这允许您在集群中的多个服务器上平均该指标的值，即使核心数量不一致，也仍然可以获得平均资源利用率指标', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10479, 'clickhouse_asynchronous_metrics_os_memory_available_desc', 'zh', 'clickhouse_asynchronous_metrics_os_memory_available_desc', '程序可使用的内存量，以字节为单位。这与“OSMemoryFreePlusCached”度量非常相似。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10480, 'clickhouse_asynchronous_metrics_os_memory_buffers_desc', 'zh', 'clickhouse_asynchronous_metrics_os_memory_buffers_desc', 'OS内核缓冲区使用的内存量，以字节为单位。这通常应该很小，大值可能表示操作系统配置错误。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10481, 'clickhouse_asynchronous_metrics_os_memory_cached_desc', 'zh', 'clickhouse_asynchronous_metrics_os_memory_cached_desc', 'OS页面缓存使用的内存量，以字节为单位。通常，几乎所有可用内存都由OS页面缓存使用-此指标的高值是正常的，也是预期的。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10482, 'clickhouse_asynchronous_metrics_os_memory_free_plus_cached_desc', 'zh', 'clickhouse_asynchronous_metrics_os_memory_free_plus_cached_desc', '主机系统上的可用内存加上操作系统页面缓存内存的数量，以字节为单位。此内存可供程序使用。该值应非常类似于“OSMemoryAvailable”。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10483, 'clickhouse_asynchronous_metrics_os_memory_free_without_cached_desc', 'zh', 'clickhouse_asynchronous_metrics_os_memory_free_without_cached_desc', '主机系统上的可用内存量，以字节为单位。这不包括OS页面缓存内存使用的内存（以字节为单位）。页面缓存内存也可供程序使用，因此该指标的值可能令人困惑。请改用“OSMemoryAvailable”度量。为了方便起见，我们还提供了“OSMemoryFreePlusCached”度量，该度量应该与OSMemoryAvailable有些类似。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10484, 'clickhouse_asynchronous_metrics_os_memory_swap_cached_desc', 'zh', 'clickhouse_asynchronous_metrics_os_memory_swap_cached_desc', '加载到RAM中的交换内存量。应在生产系统上禁用交换。如果此度量值较大，则表示配置错误。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10485, 'clickhouse_asynchronous_metrics_os_memory_total_desc', 'zh', 'clickhouse_asynchronous_metrics_os_memory_total_desc', '主机系统上的内存总量，以字节为单位', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10486, 'clickhouse_asynchronous_metrics_os_nice_time_desc', 'zh', 'clickhouse_asynchronous_metrics_os_nice_time_desc', 'CPU核心运行具有较高优先级的用户空间代码的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10487, 'clickhouse_asynchronous_metrics_os_nice_time_cpu0_desc', 'zh', 'clickhouse_asynchronous_metrics_os_nice_time_cpu0_desc', 'CPU核心运行具有较高优先级的用户空间代码的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10488, 'clickhouse_asynchronous_metrics_os_nice_time_cpu1_desc', 'zh', 'clickhouse_asynchronous_metrics_os_nice_time_cpu1_desc', 'CPU核心运行具有较高优先级的用户空间代码的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
