INSERT INTO `sys_i18n` VALUES (10494, 'clickhouse_asynchronous_metrics_os_nice_time_cpu7_desc', 'zh', 'clickhouse_asynchronous_metrics_os_nice_time_cpu7_desc', 'CPU核心运行具有较高优先级的用户空间代码的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10495, 'clickhouse_asynchronous_metrics_os_nice_time_normalized_desc', 'zh', 'clickhouse_asynchronous_metrics_os_nice_time_normalized_desc', '该值类似于“OSNiceTime”，但除以[0..1]间隔内要测量的CPU核数，而不考虑核数。这允许您在集群中的多个服务器上平均该指标的值，即使核心数量不一致，也仍然可以获得平均资源利用率指标', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10496, 'clickhouse_asynchronous_metrics_os_open_files_desc', 'zh', 'clickhouse_asynchronous_metrics_os_open_files_desc', '主机上打开的文件总数。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10497, 'clickhouse_asynchronous_metrics_os_processes_blocked_desc', 'zh', 'clickhouse_asynchronous_metrics_os_processes_blocked_desc', '等待I/O完成而被阻塞的线程数（“man procfs”）。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10498, 'clickhouse_asynchronous_metrics_os_processes_created_desc', 'zh', 'clickhouse_asynchronous_metrics_os_processes_created_desc', '创建的进程数。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10499, 'clickhouse_asynchronous_metrics_os_processes_running_desc', 'zh', 'clickhouse_asynchronous_metrics_os_processes_running_desc', '操作系统可运行（正在运行或准备运行）的线程数。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10500, 'clickhouse_asynchronous_metrics_os_soft_irq_time_desc', 'zh', 'clickhouse_asynchronous_metrics_os_soft_irq_time_desc', '在CPU上运行软件中断请求所花费的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。该度量的高数量可能指示系统上运行的软件效率低下。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10501, 'clickhouse_asynchronous_metrics_os_soft_irq_time_cpu0_desc', 'zh', 'clickhouse_asynchronous_metrics_os_soft_irq_time_cpu0_desc', '在CPU上运行软件中断请求所花费的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。该度量的高数量可能指示系统上运行的软件效率低下。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
