INSERT INTO `sys_i18n` VALUES (10509, 'clickhouse_asynchronous_metrics_os_soft_irq_time_normalized_desc', 'zh', 'clickhouse_asynchronous_metrics_os_soft_irq_time_normalized_desc', '该值类似于“OSSoftIrqTime”，但除以[0..1]间隔内要测量的CPU核数，而不考虑核数。这允许您在集群中的多个服务器上平均该指标的值，即使核心数量不一致，也仍然可以获得平均资源利用率指标', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10510, 'clickhouse_asynchronous_metrics_os_steal_time_desc', 'zh', 'clickhouse_asynchronous_metrics_os_steal_time_desc', '在虚拟化环境中运行时，CPU在其他操作系统中花费的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。并非每一个虚拟化环境都有此指标，而且大多数虚拟化环境没有。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
