INSERT INTO `sys_i18n` VALUES (10526, 'clickhouse_asynchronous_metrics_os_system_time_cpu5_desc', 'zh', 'clickhouse_asynchronous_metrics_os_system_time_cpu5_desc', 'CPU内核运行OS内核（系统）代码的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10527, 'clickhouse_asynchronous_metrics_os_system_time_cpu6_desc', 'zh', 'clickhouse_asynchronous_metrics_os_system_time_cpu6_desc', 'CPU内核运行OS内核（系统）代码的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10528, 'clickhouse_asynchronous_metrics_os_system_time_cpu7_desc', 'zh', 'clickhouse_asynchronous_metrics_os_system_time_cpu7_desc', 'CPU内核运行OS内核（系统）代码的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10529, 'clickhouse_asynchronous_metrics_os_system_time_normalized_desc', 'zh', 'clickhouse_asynchronous_metrics_os_system_time_normalized_desc', '该值类似于“OSSystemTime”，但除以[0..1]间隔内要测量的CPU核数，而不考虑核数。这允许您在集群中的多个服务器上平均该指标的值，即使核心数量不一致，也仍然可以获得平均资源利用率指标', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10530, 'clickhouse_asynchronous_metrics_os_threads_runnable_desc', 'zh', 'clickhouse_asynchronous_metrics_os_threads_runnable_desc', 'OS内核调度程序看到的“可运行”线程总数', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10531, 'clickhouse_asynchronous_metrics_os_threads_total_desc', 'zh', 'clickhouse_asynchronous_metrics_os_threads_total_desc', 'OS内核调度程序看到的线程总数', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10532, 'clickhouse_asynchronous_metrics_os_uptime_desc', 'zh', 'clickhouse_asynchronous_metrics_os_uptime_desc', '主机服务器（运行ClickHouse的计算机）的正常运行时间（秒）', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10533, 'clickhouse_asynchronous_metrics_os_user_time_desc', 'zh', 'clickhouse_asynchronous_metrics_os_user_time_desc', 'CPU核心运行用户空间代码的时间比率。这是一个系统范围的度量，它包括主机上的所有进程，而不仅仅是clickhouse服务器。这还包括由于CPU内部原因（内存负载、管道暂停、分支预测失误、运行另一个SMT内核）导致CPU利用率不足的时间。单个CPU核的值将在间隔[0..1]内。所有CPU核的数值将以它们之间的总和[0..num核]计算', '', '2023-03-20 14:40:00', 415);
