INSERT INTO `sys_i18n` VALUES (10566, 'clickhouse_asynchronous_metrics_uncompressed_cache_bytes_desc', 'zh', 'clickhouse_asynchronous_metrics_uncompressed_cache_bytes_desc', '未压缩缓存的总大小（字节）。未压缩的缓存通常不会提高性能，应该尽量避免', '', '2023-03-20 14:40:00', 415);
INSERT INTO `sys_i18n` VALUES (10567, 'clickhouse_asynchronous_metrics_uncompressed_cache_cells_desc', 'zh', 'clickhouse_asynchronous_metrics_uncompressed_cache_cells_desc', '未压缩缓存中的条目总数。每个条目代表一个解压缩的数据块。未压缩的缓存通常不会提高性能，应该尽量避免', '', '2023-03-20 14:40:00', 415);
