INSERT INTO `sys_i18n` VALUES (12161, 'clickhouse_asynchronous_metrics_block_write_bytes_sda_desc', 'en', 'clickhouse_asynchronous_metrics_block_write_bytes_sda_desc', 'Write the number of bytes of the block equipment. Because the OS page cache is used, it can be lower than the number of bytes written to the file system, thereby saving IO. Since the writing of the block can be written through the cache, the time to write the block may be later than the writing system. This is a systematic range, which includes all processes on the host', '', '2023-03-21 10:40:00', 415);
