INSERT INTO `sys_i18n` VALUES (12220, 'clickhouse_asynchronous_metrics_jitter_desc', 'en', 'clickhouse_asynchronous_metrics_jitter_desc', 'The difference between the time between the thread plan to calculate the asynchronous measurement and the actual awakening time. Acting indicator of the overall system delay and response', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12221, 'clickhouse_asynchronous_metrics_load_average1_desc', 'en', 'clickhouse_asynchronous_metrics_load_average1_desc', 'The entire system load is smooth with the index in 1 minute. The load represents the number of threads on all processes (scheduling entities of the OS kernel). These threads are currently running or waiting for IO by CPU, or they are ready to run, but they are not scheduled at this time. This number includes all processes', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12222, 'clickhouse_asynchronous_metrics_load_average15_desc', 'en', 'clickhouse_asynchronous_metrics_load_average15_desc', 'The entire system load is smooth with the index smoothly within 15 minutes. The load represents the number of threads on all processes (scheduling entities of the OS kernel). These threads are currently running or waiting for IO by CPU, or they are ready to run, but they are not scheduled at this time. This number includes all processes', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12223, 'clickhouse_asynchronous_metrics_load_average5_desc', 'en', 'clickhouse_asynchronous_metrics_load_average5_desc', 'The entire system load is smooth with the index smoothly within 5 minutes. The load represents the number of threads on all processes (scheduling entities of the OS kernel). These threads are currently running or waiting for IO by CPU, or they are ready to run, but they are not scheduled at this time. This number includes all processes', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12224, 'clickhouse_asynchronous_metrics_m_map_cache_cells_desc', 'en', 'clickhouse_asynchronous_metrics_m_map_cache_cells_desc', 'The number of files opened by \"mmap\" (mapped into memory). This is used to query \"LOCAL_FILESYSTEM_READ_READ_METHOD\" to \"mmap\". Save the files opened by \"MMAP\" in the cache to avoid expensive TLB refresh', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12225, 'clickhouse_asynchronous_metrics_mark_cache_bytes_desc', 'en', 'clickhouse_asynchronous_metrics_mark_cache_bytes_desc', 'The total size of the label cache (byte)', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12226, 'clickhouse_asynchronous_metrics_mark_cache_files_desc', 'en', 'clickhouse_asynchronous_metrics_mark_cache_files_desc', 'Total number of tag files in the cache cache cache', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12227, 'clickhouse_asynchronous_metrics_max_part_count_for_partition_desc', 'en', 'clickhouse_asynchronous_metrics_max_part_count_for_partition_desc', 'The maximum number of each partition of all partitions of the Mergetree tribe. Value greater than 300 means configuration error, overload or large amount of data loading', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12228, 'clickhouse_asynchronous_metrics_memory_code_desc', 'en', 'clickhouse_asynchronous_metrics_memory_code_desc', 'Machine code page mapping for server processes, virtual internal stocks, in bytes as units', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12229, 'clickhouse_asynchronous_metrics_memory_data_and_stack_desc', 'en', 'clickhouse_asynchronous_metrics_memory_data_and_stack_desc', 'The virtual internal stocks mapped to use stacks and allocated memory, bytes are based on bytes. Whether it includes each thread stack and most of the allocated memory, which is allocated and allocated through the \"MMAP\" system, which has not been clear. This measure exists only for integrity. It is recommended to use \"MemoryReSIDENT\" measurement to monitor', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12230, 'clickhouse_asynchronous_metrics_memory_resident_desc', 'en', 'clickhouse_asynchronous_metrics_memory_resident_desc', 'The physical memory used in the server process is based on byte', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12231, 'clickhouse_asynchronous_metrics_memory_shared_desc', 'en', 'clickhouse_asynchronous_metrics_memory_shared_desc', 'The amount of memory used by the server process is also shared by other processes, which is based on bytes. Clickhouse does not use shared memory, but for its own reasons, certain memory may be marked by OS as sharing. This indicator does not make much meaning, its existence is only due to integrity', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12232, 'clickhouse_asynchronous_metrics_memory_virtual_desc', 'en', 'clickhouse_asynchronous_metrics_memory_virtual_desc', 'The size of the virtual address space distributed by the server process is based on byte. The size of the virtual address space is usually much greater than the physical memory, and it is not used as an estimated value for memory consumption. The large value of this measure is completely normal, and it is only technically meaningful', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12233, 'clickhouse_asynchronous_metrics_my_sql_threads_desc', 'en', 'clickhouse_asynchronous_metrics_my_sql_threads_desc', 'The number of threads in mysql compatible protocol server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12234, 'clickhouse_asynchronous_metrics_network_receive_bytes_ens33_desc', 'en', 'clickhouse_asynchronous_metrics_network_receive_bytes_ens33_desc', 'Number of bytes received through network interface. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
