INSERT INTO `sys_i18n` VALUES (12258, 'clickhouse_asynchronous_metrics_number_of_databases_desc', 'en', 'clickhouse_asynchronous_metrics_number_of_databases_desc', 'The total number of databases on the server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12259, 'clickhouse_asynchronous_metrics_number_of_detached_by_user_parts_desc', 'en', 'clickhouse_asynchronous_metrics_number_of_detached_by_user_parts_desc', 'The user uses the \"Alter Table Detach\" to query the total number of parts separated from the Mergetree table (the contrary to the parts of accidents, damage or ignoring). The server does not care about separation components, they can be removed', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12260, 'clickhouse_asynchronous_metrics_number_of_detached_parts_desc', 'en', 'clickhouse_asynchronous_metrics_number_of_detached_parts_desc', 'Total number of parts separated from the Mergetree table. Users can use \"Alter Table Detach\" to query separate parts, or separate parts by the server itself when parts damage, accident or not needed. The server does not care about separation components, they can be removed', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12261, 'clickhouse_asynchronous_metrics_number_of_tables_desc', 'en', 'clickhouse_asynchronous_metrics_number_of_tables_desc', 'The total number of databases on the server does not include databases that cannot include the Mergetree table. The excluded database engine is the engines that dynamically generate table sets, such', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12262, 'clickhouse_asynchronous_metrics_os_context_switches_desc', 'en', 'clickhouse_asynchronous_metrics_os_context_switches_desc', 'The number of text switching of the system experienced on the host. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12263, 'clickhouse_asynchronous_metrics_os_guest_nice_time_desc', 'en', 'clickhouse_asynchronous_metrics_os_guest_nice_time_desc', 'When the guest is set to a higher priority, the time ratio spent (see \"Man-PROCFS\") for the guest operating system under the control of the Linux kernel. This is a systematic range, which includes all processes on the host, not just the Clickhouse server. This indicator has nothing to do with the clickhouse, but still has integrity. The value of a single CPU core will be within the interval [0..1]. The value of all CPU kernels will be calculated based on the sum of them [0.. Num Nuclear]', '', '2023-03-21 10:40:00', 415);
