INSERT INTO `sys_i18n` VALUES (12292, 'clickhouse_asynchronous_metrics_os_idle_time_normalized_desc', 'en', 'clickhouse_asynchronous_metrics_os_idle_time_normalized_desc', 'This value is similar to \"Osidletime\", but the CPU nuclear number to be measured in addition to the [0..1] interval is not considered without considering the nuclear number. This allows you to the average value of the indicator on multiple servers in the cluster. Even if the core number is inconsistent, you can still get the average resource utilization index', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12293, 'clickhouse_asynchronous_metrics_os_interrupts_desc', 'en', 'clickhouse_asynchronous_metrics_os_interrupts_desc', 'The number of interruptions on the host. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12294, 'clickhouse_asynchronous_metrics_os_irq_time_desc', 'en', 'clickhouse_asynchronous_metrics_os_irq_time_desc', 'Run the time ratio of hardware interrupt requests on the CPU. This is a systematic range, which includes all processes on the host, not just the Clickhouse server. The high value of this measurement value may mean that the hardware configuration error or the network load is very high. The value of a single CPU core will be within the interval [0..1]. The value of all CPU kernels will be calculated based on the sum of them [0.. Num Nuclear]', '', '2023-03-21 10:40:00', 415);
