INSERT INTO `sys_i18n` VALUES (12304, 'clickhouse_asynchronous_metrics_os_memory_available_desc', 'en', 'clickhouse_asynchronous_metrics_os_memory_available_desc', 'The amount of memory available in the program is based on bytes. This is very similar to the measurement of \"OsmemoryFreeplusCached\". This is a systematic range, which includes all processes on the host, not just the Clickhouse server.', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12305, 'clickhouse_asynchronous_metrics_os_memory_buffers_desc', 'en', 'clickhouse_asynchronous_metrics_os_memory_buffers_desc', 'The memory amount used in the OS kernel buffer is based on bytes. This should usually be small, and the large value may indicate an error of the operating system configuration. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12306, 'clickhouse_asynchronous_metrics_os_memory_cached_desc', 'en', 'clickhouse_asynchronous_metrics_os_memory_cached_desc', 'The amount of memory used in the OS page is based on byte. Generally, almost all available memory is used by the OS page to use-the high value of this indicator is normal and expected. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12307, 'clickhouse_asynchronous_metrics_os_memory_free_plus_cached_desc', 'en', 'clickhouse_asynchronous_metrics_os_memory_free_plus_cached_desc', 'The available memory on the host system plus the number of operating system page cache memory, which is based on bytes. This memory is available for programming. This value should be very similar to \"OsMemoryavailable\". This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12308, 'clickhouse_asynchronous_metrics_os_memory_free_without_cached_desc', 'en', 'clickhouse_asynchronous_metrics_os_memory_free_without_cached_desc', 'The available memory amount on the host system is based on bytes. This does not include memory (by bytes) for cache memory used. The page cache memory can also be used for programming, so the value of the indicator may be confusing. Please use \"OsMemoryavailable\" to measure. For the sake of convenience, we also provide \"OsmemoryFreeplusCached\" measuring, which should be similar to OsMemoryavailable. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12309, 'clickhouse_asynchronous_metrics_os_memory_swap_cached_desc', 'en', 'clickhouse_asynchronous_metrics_os_memory_swap_cached_desc', 'Load the exchange memory in RAM. Exchange should be disabled on the production system. If this measure is large, the configuration is wrong. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12310, 'clickhouse_asynchronous_metrics_os_memory_total_desc', 'en', 'clickhouse_asynchronous_metrics_os_memory_total_desc', 'The total memory on the host system is based on bytes', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12311, 'clickhouse_asynchronous_metrics_os_nice_time_desc', 'en', 'clickhouse_asynchronous_metrics_os_nice_time_desc', 'The CPU core operation has a high priority user space code. This is a systematic range, which includes all processes on the host, not just the Clickhouse server. The value of a single CPU core will be within the interval [0..1]. The value of all CPU kernels will be calculated based on the sum of them [0.. Num Nuclear]', '', '2023-03-21 10:40:00', 415);
