INSERT INTO `sys_i18n` VALUES (12321, 'clickhouse_asynchronous_metrics_os_open_files_desc', 'en', 'clickhouse_asynchronous_metrics_os_open_files_desc', 'Total number of files opened on the host. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12322, 'clickhouse_asynchronous_metrics_os_processes_blocked_desc', 'en', 'clickhouse_asynchronous_metrics_os_processes_blocked_desc', 'Waiting for the number of threads (\"Man ProCFS\") to be obstructed. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12323, 'clickhouse_asynchronous_metrics_os_processes_created_desc', 'en', 'clickhouse_asynchronous_metrics_os_processes_created_desc', 'Create the number of processes. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12324, 'clickhouse_asynchronous_metrics_os_processes_running_desc', 'en', 'clickhouse_asynchronous_metrics_os_processes_running_desc', 'The number of threads that can be run (running or preparing to run) operating systems. This is a systematic range, which includes all the processes on the host, not just the Clickhouse server', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12325, 'clickhouse_asynchronous_metrics_os_soft_irq_time_desc', 'en', 'clickhouse_asynchronous_metrics_os_soft_irq_time_desc', 'The time ratio spent on running software interruption on the CPU. This is a systematic range, which includes all processes on the host, not just the Clickhouse server. The high quantity of the measurement may indicate that the software running on the system is low. The value of a single CPU core will be within the interval [0..1]. The value of all CPU kernels will be calculated based on the sum of them [0.. Num Nuclear]', '', '2023-03-21 10:40:00', 415);
