INSERT INTO `sys_i18n` VALUES (12335, 'clickhouse_asynchronous_metrics_os_steal_time_desc', 'en', 'clickhouse_asynchronous_metrics_os_steal_time_desc', 'When running in a virtualized environment, the CPU spends the time ratio in other operating systems. This is a systematic range, which includes all processes on the host, not just the Clickhouse server. Not every virtualized environment has this indicator, and most virtualized environments are not. The value of a single CPU core will be within the interval [0..1]. The value of all CPU kernels will be calculated based on the sum of them [0.. Num Nuclear]', '', '2023-03-21 10:40:00', 415);
