INSERT INTO `sys_i18n` VALUES (12344, 'clickhouse_asynchronous_metrics_os_steal_time_normalized_desc', 'en', 'clickhouse_asynchronous_metrics_os_steal_time_normalized_desc', 'This value is similar to \"OSSttealtTime\", but the CPU nuclear number to be measured in the interval of [0..1] is not considered without considering the nuclear number. This allows you to the average value of the indicator on multiple servers in the cluster. Even if the core number is inconsistent, you can still get the average resource utilization index', '', '2023-03-21 10:40:00', 415);
