INSERT INTO `sys_i18n` VALUES (12355, 'clickhouse_asynchronous_metrics_os_threads_runnable_desc', 'en', 'clickhouse_asynchronous_metrics_os_threads_runnable_desc', 'The total number of \"running\" threads seen by the OS kernel scheduling program', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12356, 'clickhouse_asynchronous_metrics_os_threads_total_desc', 'en', 'clickhouse_asynchronous_metrics_os_threads_total_desc', 'The total number of threads seen in the OS kernel scheduling program', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12357, 'clickhouse_asynchronous_metrics_os_uptime_desc', 'en', 'clickhouse_asynchronous_metrics_os_uptime_desc', 'The normal running time (second) of the host server (computer running a computer)', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12358, 'clickhouse_asynchronous_metrics_os_user_time_desc', 'en', 'clickhouse_asynchronous_metrics_os_user_time_desc', 'The time ratio of CPU core running user space code. This is a systematic range, which includes all processes on the host, not just the Clickhouse server. This also includes the time due to the internal reasons of the CPU (memory load, pipeline suspension, branch prediction errors, and running another SMT kernel). The value of a single CPU core will be within the interval [0..1]. The value of all CPU kernels will be calculated based on the sum of them [0.. Num Nuclear]', '', '2023-03-21 10:40:00', 415);
