INSERT INTO `sys_i18n` VALUES (12368, 'clickhouse_asynchronous_metrics_osio_wait_time_desc', 'en', 'clickhouse_asynchronous_metrics_osio_wait_time_desc', 'The CPU kernel did not run code but the OS kernel did not run any other processes on the CPU when waiting for IO. This is a systematic range, which includes all processes on the host, not just the Clickhouse server. The value of a single CPU core will be within the interval [0..1]. The value of all CPU kernels will be calculated based on the sum of them [0.. Num Nuclear]', '', '2023-03-21 10:40:00', 415);
