INSERT INTO `sys_i18n` VALUES (12378, 'clickhouse_asynchronous_metrics_postgre_sql_threads_desc', 'en', 'clickhouse_asynchronous_metrics_postgre_sql_threads_desc', 'PostgreSQL compatible protocol server number of threads', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12379, 'clickhouse_asynchronous_metrics_replicas_max_absolute_delay_desc', 'en', 'clickhouse_asynchronous_metrics_replicas_max_absolute_delay_desc', 'In the duplicate table, the maximum difference between the latest copy and the latest data parts that still want to copy (seconds). Very high value indicates that there is no data for copying the copy', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12380, 'clickhouse_asynchronous_metrics_replicas_max_inserts_in_queue_desc', 'en', 'clickhouse_asynchronous_metrics_replicas_max_inserts_in_queue_desc', 'The maximum number of INSERT operations in the queue (still to be copied)', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12381, 'clickhouse_asynchronous_metrics_replicas_max_merges_in_queue_desc', 'en', 'clickhouse_asynchronous_metrics_replicas_max_merges_in_queue_desc', 'The maximum number of merging operations in the queue (still to be applied)', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12382, 'clickhouse_asynchronous_metrics_replicas_max_queue_size_desc', 'en', 'clickhouse_asynchronous_metrics_replicas_max_queue_size_desc', 'The maximum queue of the copy table (represented by the number of acquisition, merger and other operations)', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12383, 'clickhouse_asynchronous_metrics_replicas_max_relative_delay_desc', 'en', 'clickhouse_asynchronous_metrics_replicas_max_relative_delay_desc', 'The maximum difference between the copy of the copy delay and the latest copy of the copy of the same table (cross -copy table)', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12384, 'clickhouse_asynchronous_metrics_replicas_sum_inserts_in_queue_desc', 'en', 'clickhouse_asynchronous_metrics_replicas_sum_inserts_in_queue_desc', 'The total number of INSERT operations in the Copy Table (still need to be copied)', '', '2023-03-21 10:40:00', 415);
