INSERT INTO `sys_i18n` VALUES (12386, 'clickhouse_asynchronous_metrics_replicas_sum_queue_size_desc', 'en', 'clickhouse_asynchronous_metrics_replicas_sum_queue_size_desc', 'Copy the summary of the queue in the table (represented by the number of acquisition, merger and other operations)', '', '2023-03-21 10:40:00', 415);
INSERT INTO `sys_i18n` VALUES (12387, 'clickhouse_asynchronous_metrics_tcp_threads_desc', 'en', 'clickhouse_asynchronous_metrics_tcp_threads_desc', 'TCP protocol (excluding TLS) server number of threads', '', '2023-03-21 10:40:00', 415);
